//! The Opal Optimizer's upstream tables, extracted from the calculators.
//!
//! Every table is generated by `script/extract-opal-data.mjs` from
//! `Corgan/idleon-research-optimizer`; nothing is hand-typed. The bell and
//! measurement rows live next door in `fountain.json`, extracted from the same
//! upstream rows.

use serde::Deserialize;
use std::sync::OnceLock;

const OPAL_JSON: &str = include_str!("../../data/opal.json");

/// The tables `buildExt` and its helpers read.
#[derive(Debug, Deserialize)]
pub struct OpalData {
    /// `CosmoUpgrades[tier][i][0]`: the per-level base of each cosmo upgrade.
    pub cosmo: Vec<Vec<f64>>,
    /// `CompassUpg[i][5]`: the per-level bonus of each compass upgrade.
    #[serde(rename = "compassPerLevel")]
    pub compass_per_level: Vec<f64>,
    /// `CompassUpg[i][9]`: 1 when the bonus also scales with the circle upgrades.
    #[serde(rename = "compassConditional")]
    pub compass_conditional: Vec<f64>,
    /// `pristineCharmBonus(i)` from `js/stats/data/common/sigils.js`.
    pub pristine: Vec<f64>,
    /// `GrimoireUpg[i][5]`: the per-level bonus of each grimoire upgrade.
    #[serde(rename = "grimoirePerLevel")]
    pub grimoire_per_level: Vec<f64>,
    /// The grimoire upgrades outside the ×Grimoire-36 multiplier.
    #[serde(rename = "grimoireNoMulti")]
    pub grimoire_no_multi: Vec<u32>,
    /// `StatueInfo[i][3]`: the bonus each statue level grants.
    #[serde(rename = "statueBase")]
    pub statue_base: Vec<f64>,
    /// `ZenithMarket[i][4]`: the bonus each Zenith Market level grants.
    #[serde(rename = "zenithPerLevel")]
    pub zenith_per_level: Vec<f64>,
    /// `Spelunky[21]`: the `base|threshold` pair behind each Lore Episode.
    #[serde(rename = "spelunkyLore")]
    pub spelunky_lore: Vec<String>,
    /// `HolesInfo[37]`: the per-slot monument bonus, `slot = 10 × row + index`.
    #[serde(rename = "holesMonument")]
    pub holes_monument: Vec<f64>,
    /// `TalentDescriptions[56][1]`: the All Statues talent curve.
    #[serde(rename = "statueTalent")]
    pub statue_talent: TalentCurve,
}

/// One talent's curve: `formula(x1, x2, level)`.
#[derive(Clone, Debug, Deserialize)]
pub struct TalentCurve {
    pub x1: f64,
    pub x2: f64,
    /// The upstream formula name; the All Statues talent uses `decay`.
    pub formula: String,
}

impl TalentCurve {
    /// The talent's value at `level`, for the one formula the opal page reads.
    pub fn value(&self, level: f64) -> f64 {
        if level <= 0.0 {
            return 0.0;
        }
        match self.formula.as_str() {
            "decay" => self.x1 * level / (self.x2 + level),
            _ => 0.0,
        }
    }
}

/// The All Statues talent curve, for the statue chain's talent-56 term.
pub fn talent_curve() -> &'static TalentCurve {
    &data().statue_talent
}

pub(crate) fn data() -> &'static OpalData {
    static DATA: OnceLock<OpalData> = OnceLock::new();
    DATA.get_or_init(|| {
        serde_json::from_str(OPAL_JSON).expect("crates/core/data/opal.json is extracted")
    })
}

/// `cosmoUpgBase(tier, index)`.
pub(crate) fn cosmo_base(tier: usize, index: usize) -> f64 {
    data()
        .cosmo
        .get(tier)
        .and_then(|row| row.get(index))
        .copied()
        .unwrap_or(0.0)
}

/// `CompassUpg`: the per-level bonus and the conditional flag of one upgrade.
pub(crate) fn compass(index: usize) -> (f64, bool) {
    let per_level = data().compass_per_level.get(index).copied().unwrap_or(0.0);
    let conditional = data()
        .compass_conditional
        .get(index)
        .copied()
        .unwrap_or(0.0)
        == 1.0;
    (per_level, conditional)
}

/// `pristineCharmBonus(index)`.
pub(crate) fn pristine(index: usize) -> f64 {
    data().pristine.get(index).copied().unwrap_or(0.0)
}

/// `GrimoireUpg[index][5]` and whether the upgrade skips the ×36 multiplier.
pub(crate) fn grimoire(index: usize) -> (f64, bool) {
    let per_level = data().grimoire_per_level.get(index).copied().unwrap_or(0.0);
    let no_multi = data().grimoire_no_multi.contains(&(index as u32));
    (per_level, no_multi)
}

/// `StatueInfo[index][3]`.
pub(crate) fn statue_base(index: usize) -> f64 {
    data().statue_base.get(index).copied().unwrap_or(0.0)
}

/// `ZenithMarket[index][4]`.
pub(crate) fn zenith(index: usize) -> f64 {
    data().zenith_per_level.get(index).copied().unwrap_or(0.0)
}

/// `Spelunky[21][index]`, split into its base value and point threshold.
pub(crate) fn lore_episode(index: usize) -> (f64, f64) {
    let Some(entry) = data().spelunky_lore.get(index) else {
        return (0.0, 0.0);
    };
    let mut parts = entry.split('|');
    let base = parts.next().and_then(|part| part.trim().parse().ok());
    let threshold = parts.next().and_then(|part| part.trim().parse().ok());
    (base.unwrap_or(0.0), threshold.unwrap_or(0.0))
}

/// `HolesInfo[37][slot]`.
pub(crate) fn monument_slot(slot: usize) -> f64 {
    data().holes_monument.get(slot).copied().unwrap_or(0.0)
}
